-- SVS-05 catalog-only inspection. Execute as the actual dedicated validator login.
-- No account/session rows, password values, tokens or signing material are read.
with identities as (
 select oid,rolname from pg_catalog.pg_roles where rolname in ('treehammock_svs','treehammock_svs_read')
), user_relations as (
 select c.*,n.nspname from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
 where n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg_toast%' and n.nspname not like 'pg_temp%'
), unsafe as (
 select 'Ownership'::text code where exists(select 1 from pg_catalog.pg_shdepend s where s.refclassid='pg_catalog.pg_authid'::regclass and s.refobjid in (select oid from identities) and s.deptype in ('o','i'))
 union all select 'TableDefinition' where (select count(*) from user_relations where nspname='public' and relname in ('accounts','sessions','entitlement_grants','entitlement_grant_audit') and relkind='r' and not relrowsecurity and not relforcerowsecurity)<>4
 union all select 'SystemWrite' where exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace cross join identities i where n.nspname in ('pg_catalog','information_schema') and c.relkind in ('r','v','m','f','p') and (has_table_privilege(i.oid,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(i.oid,c.oid,'INSERT,UPDATE,REFERENCES')))
 union all select 'DatabasePrivilege' where exists(select 1 from pg_catalog.pg_database d cross join identities i where (d.datname<>current_database() and d.datallowconn and has_database_privilege(i.oid,d.oid,'CONNECT')) or has_database_privilege(i.oid,d.oid,'CREATE,TEMP') or has_database_privilege(i.oid,d.oid,'CONNECT WITH GRANT OPTION'))
 union all select 'SchemaPrivilege' where exists(select 1 from pg_catalog.pg_namespace n cross join identities i where n.nspname not like 'pg_temp%' and n.nspname not like 'pg_toast%' and (has_schema_privilege(i.oid,n.oid,'CREATE') or has_schema_privilege(i.oid,n.oid,'USAGE WITH GRANT OPTION') or (n.nspname not in ('public','pg_catalog','information_schema') and has_schema_privilege(i.oid,n.oid,'USAGE'))))
 union all select 'TableWrite' where exists(select 1 from user_relations c cross join identities i where c.relkind in ('r','p','v','m','f') and has_table_privilege(i.oid,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))
 union all select 'ColumnWriteOrDelegation' where exists(select 1 from user_relations c join pg_catalog.pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped cross join identities i where c.relkind in ('r','p','v','m','f') and has_column_privilege(i.oid,c.oid,a.attnum,'INSERT,UPDATE,REFERENCES,SELECT WITH GRANT OPTION'))
 union all select 'SequencePrivilege' where exists(select 1 from user_relations c cross join identities i where c.relkind='S' and has_sequence_privilege(i.oid,c.oid,'USAGE,SELECT,UPDATE'))
 union all select 'AuthCatalogPrivilege' where exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace cross join identities i where n.nspname='pg_catalog' and c.relname in ('pg_authid','pg_shadow') and (has_table_privilege(i.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(i.oid,c.oid,'SELECT,INSERT,UPDATE,REFERENCES')))
 union all select 'RiskyBuiltin' where exists(select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace cross join identities i where n.nspname='pg_catalog' and (p.proname like 'lo\_%' escape '\' or p.proname in ('loopen','loclose','loread','lowrite','pg_read_file','pg_read_binary_file','pg_stat_file','pg_ls_dir')) and has_function_privilege(i.oid,p.oid,'EXECUTE'))
 union all select 'FunctionDelegation' where exists(select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace cross join identities i where n.nspname not in ('pg_catalog','information_schema') and has_function_privilege(i.oid,p.oid,'EXECUTE WITH GRANT OPTION'))
 union all select 'FuturePrivilege' where exists(select 1 from pg_catalog.pg_default_acl d cross join lateral pg_catalog.aclexplode(d.defaclacl) a where a.grantee=0 or a.grantee in (select oid from identities))
 union all select 'FuturePublicFunction' where exists(select 1 from pg_catalog.pg_roles r left join pg_catalog.pg_default_acl d on d.defaclrole=r.oid and d.defaclnamespace=0 and d.defaclobjtype='f' cross join lateral pg_catalog.aclexplode(coalesce(d.defaclacl,pg_catalog.acldefault('f',r.oid))) a where a.grantee=0 and a.privilege_type='EXECUTE')
)
select pg_catalog.jsonb_build_object(
 'sessionUser',session_user,'currentUser',current_user,
 'roles',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',r.rolname,'login',r.rolcanlogin,'superuser',r.rolsuper,'createDb',r.rolcreatedb,'createRole',r.rolcreaterole,'inherit',r.rolinherit,'replication',r.rolreplication,'bypassRls',r.rolbypassrls,'connectionLimit',r.rolconnlimit) order by r.rolname) from pg_catalog.pg_roles r join identities i on i.oid=r.oid),'[]'::jsonb),
 'memberships',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('member',i.rolname,'role',r.rolname,'admin',coalesce((select pg_catalog.bool_or(m.admin_option) from pg_catalog.pg_auth_members m where m.member=i.oid and m.roleid=r.oid),false)) order by i.rolname,r.rolname) from identities i cross join pg_catalog.pg_roles r where r.oid<>i.oid and pg_catalog.pg_has_role(i.oid,r.oid,'MEMBER')),'[]'::jsonb),
 'columns',coalesce((select pg_catalog.jsonb_agg(k order by k) from (select distinct c.nspname||'.'||c.relname||'.'||a.attname k from user_relations c join pg_catalog.pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped cross join identities i where c.relkind in ('r','p','v','m','f') and pg_catalog.has_column_privilege(i.oid,c.oid,a.attnum,'SELECT')) x),'[]'::jsonb),
 'functions',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('signature',n.nspname||'.'||p.proname||'('||replace(pg_catalog.oidvectortypes(p.proargtypes),', ', ',')||')','source',p.prosrc,'language',l.lanname,'volatility',p.provolatile::text,'definer',p.prosecdef,'kind',p.prokind::text,'config',coalesce(to_jsonb(p.proconfig),'[]'::jsonb)) order by p.oid) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace join pg_catalog.pg_language l on l.oid=p.prolang where n.nspname not in ('pg_catalog','information_schema') and exists(select 1 from identities i where pg_catalog.has_function_privilege(i.oid,p.oid,'EXECUTE'))),'[]'::jsonb),
 'requiredConnect',pg_catalog.has_database_privilege('treehammock_svs',current_database(),'CONNECT'),
 'requiredUsage',pg_catalog.has_schema_privilege('treehammock_svs','public','USAGE'),
 'unsafe',coalesce((select pg_catalog.jsonb_agg(code order by code) from unsafe),'[]'::jsonb)
)::text;
